using STOREEX.Models; using STOREEX.ViewModels; using System; using System.Linq; using System.Web.Mvc;
namespace STOREEX.Controllers { [Authorize] public class POSController:Controller { readonly StoreexDb db=new StoreexDb(); const int C=1; public ActionResult Index(){ViewBag.Warehouses=new SelectList(db.Warehouses.Where(x=>x.CompanyId==C&&x.IsActive),"Id","Name");ViewBag.Customers=new SelectList(db.Customers.Where(x=>x.CompanyId==C&&x.IsActive),"Id","Name");return View();} [HttpGet] public JsonResult FindProduct(string q,int warehouseId){q=(q??"").Trim();var p=db.Products.Where(x=>x.CompanyId==C&&x.IsActive&&(x.Barcode==q||x.SKU==q||x.Name.Contains(q))).Select(x=>new{x.Id,x.Name,x.Barcode,x.SKU,x.SalePrice,x.TaxRate}).FirstOrDefault();if(p==null)return Json(new{success=false},JsonRequestBehavior.AllowGet);var stock=db.WarehouseStocks.Where(x=>x.WarehouseId==warehouseId&&x.ProductId==p.Id).Select(x=>(decimal?)x.Quantity).FirstOrDefault()??0;return Json(new{success=true,product=p,stock},JsonRequestBehavior.AllowGet);} protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);} } }